/* ================= CAPITOLO 1 — LE TRE PISTE E IL FINALE ================= */
const needBadge=async(who)=>{ if (F().distintivo) return true; await np(who,'E tu chi cazzo sei? Senza distintivo comunale qui non parli con nessuno. Vai dal sindaco, sbirro della domenica.','And who the hell are you? No town badge, no talking. Go see the mayor, Sunday cop.'); return false; };
/* ================= PISTA A: TONINO ================= */
/* --- spiaggia --- */
avOn('look:sea',()=>me('Il mare. Qualcuno ci sta nuotando vestito. Forse è un turista. Forse è un cadavere. Da qui non si capisce.','The sea. Someone is swimming fully dressed. A tourist maybe. Or a corpse. Hard to tell from here.'));
avOn('look:castle',()=>me('Un castello di sabbia con una bandierina: "PROPRIETÀ PRIVATA — BAFFO".','A sandcastle with a little flag: "PRIVATE PROPERTY — BAFFO".'));
avOn('take:castle open:castle',async()=>{ await meAct('squat',1200); if (avCoin('castle')) return np('baffo','EHI! Il mio castello! ...Va bene, tieniti il Pippi. Era la mia cassaforte di riserva.','HEY! My castle! ...Fine, keep the Pippi. It was my backup safe.'); return me('Solo sabbia. E un mozzicone. E, ok, una cosa che spero fosse cioccolato.','Just sand. A cigarette butt. And, okay, something I hope was chocolate.'); });
avOn('look:towel use:towel',()=>me('Un telo con scritto "Baffo". Anche il telo ha i baffi. Disegnati col pennarello.','A towel saying "Baffo". Even the towel has a moustache. Drawn in marker.'));
avOn('look:baffo',()=>me('Baffo il contrabbandiere. Più tatuaggi che denti, più denti d\'oro che principi.','Baffo the smuggler. More tattoos than teeth, more gold teeth than principles.'));
avOn('talk:baffo',async()=>{ const f=F();
  if (f.baffoTold) return np('baffo','Ti ho già detto tutto. Bisca, Tonino, barbiere. Ora levati dal sole, mi fai ombra sui tatuaggi.','I told you everything. Den, Tonino, barber. Now get out of the sun, you\'re shading my tattoos.');
  await avTalk('baffo',[
    {id:'tonino', q:['Hai visto uno col ciuffo lucido stanotte?','Seen a guy with a shiny quiff tonight?'], run:async()=>{ if (f.distintivo){ await np('baffo','Ah, uno sbirro. Coi distintivi io parlo solo in tribunale. Mettilo via e forse ragioniamo.','Ah, a cop. I only talk to badges in court. Put it away and maybe we can chat.'); } return np('baffo','Le informazioni costano, bello. Portami qualcosa di FORTE. Forte davvero, non quella piscia analcolica che bevete voi in paese.','Information costs, pal. Bring me something STRONG. Really strong, not that alcohol-free piss you drink in town.'); }},
    {id:'business', q:['Cosa contrabbandi?','What do you smuggle?'], run:()=>np('baffo','Sigarette, gamberi, nonne. Le nonne le porto in Svizzera, così i nipoti risparmiano sulla badante. Servizio sociale.','Cigarettes, prawns, grannies. I ship grannies to Switzerland, so grandkids save on carers. Social service.')},
    {id:'grandpa', q:['Hai mai portato in Svizzera un certo Ernesto?','Ever ship a guy called Ernesto to Switzerland?'], when:()=>F().trunk||F().bunkerSeen, run:()=>np('baffo','Ernesto? Nel 1987 mio padre portò un vecchio pazzo con una valigia piena di mappe... ma non in Svizzera. Su un\'isola. Gli disse: "Se qualcuno chiede, sono in Svizzera". Ora che ci penso, ho detto troppo.','Ernesto? In 1987 my dad took a crazy old man with a suitcase full of maps... but not to Switzerland. To an island. He said: "If anyone asks, I\'m in Switzerland". Come to think of it, I\'ve said too much.')},
    {id:'insult', q:['Sai che i tuoi baffi sembrano un topo morto?','You know your moustache looks like a dead rat?'], once:true, run:()=>np('baffo','E tu sembri la cosa che il topo ha mangiato prima di morire. Bel tentativo, pivello.','And you look like what the rat ate before it died. Nice try, rookie.')}
  ]); });
avOn('give:baffo:grappa',async()=>{ const f=F(); avDel('grappa'); await npcAct('baffo','drink',1800);
  if (f.grappaHalf) await np('baffo','Mezza bottiglia? Chi s\'è bevuto l\'altra metà, un morto? ...Ah, Ugo. Vabbè, è forte lo stesso. UUUH. Mi sono drizzati i baffi. E non solo.','Half a bottle? Who drank the rest, a corpse? ...Ah, Ugo. Fine, still strong. WHOOO. My moustache stood up. And not only that.');
  else await np('baffo','UUUH! Questa sì che è grappa! Mi si è sciolto un dente. Quello d\'oro. Lo ingoio, così lo ritrovo domani.','WHOOO! Now THAT\'s grappa! It melted a tooth. The gold one. I\'ll swallow it, find it tomorrow.');
  await np('baffo','Il ciuffo è Tonino il Liscio. Stanotte voleva vendermi il Mestolo d\'Oro. Io roba che scotta non la tocco: mi ricordo ancora il carico di cozze radioattive del 2003.','The quiff is Slick Tonino. Tonight he tried to sell me the Golden Ladle. I don\'t touch hot goods: still remember the radioactive mussels of 2003.');
  await np('baffo','È andato a giocarselo alla bisca, quella dietro il barbiere. La parola d\'ordine comincia con "Pippi"... l\'altra metà la sa Salvatore il barbiere. Io la scordo sempre, ho bevuto troppo nel \'98.','He went to gamble it at the den behind the barber\'s. The password starts with "Pippi"... the barber Salvatore knows the rest. I always forget it, drank too much in \'98.');
  f.baffoTold=1; avSave(); avAdd('biglietto'); avOpen('barber'); });
avOn('give:baffo:distintivo',()=>np('baffo','Mettimi un distintivo sotto il naso un\'altra volta e te lo faccio ingoiare. Di lato.','Shove a badge under my nose again and I\'ll make you swallow it. Sideways.'));
avOn('give:baffo:baffi',()=>np('baffo','Baffi finti? A ME? È come portare la sabbia al deserto. O le corna a tua moglie. Ops.','Fake moustache? To ME? Like bringing sand to the desert. Or horns to your wife. Oops.'));
avOn('give:baffo:caffe',()=>np('baffo','Caffè? Io bevo solo cose che bruciano lo stomaco. Il caffè lo bevono i ragionieri.','Coffee? I only drink things that burn the stomach. Coffee is for accountants.'));
/* --- barbiere --- */
avOn('look:salvatore',()=>me('Salvatore. Taglia capelli dal 1983. Sempre lo stesso taglio, "lo Stile \'83". Chi chiede altro esce rasato.','Salvatore. Cutting hair since 1983. Always the same cut, "Style \'83". Ask for anything else and you leave shaved.'));
avOn('talk:salvatore',async()=>{ const f=F();
  await avTalk('salvatore',[
    {id:'pwd', q:['Conosci la parola d\'ordine della bisca?','Do you know the den\'s password?'], when:()=>!f.gavePettine, run:async()=>{ await np('salvatore','La so, la so. Ma stanotte non dico niente a nessuno: ho perso il mio pettine portafortuna nella fontana del parco. Senza, sbaglio le basette e mi gira storta pure la vita.','I know it. But tonight I\'m not telling anyone: I lost my lucky comb in the park fountain. Without it I botch sideburns and my whole life goes crooked.');
      await np('salvatore','Me lo riporti e ti dico tutto. Pure i segreti delle clienti. Quelli valgono più della bisca.','Bring it back and I\'ll tell you everything. Even my clients\' secrets. Those are worth more than the den.'); f.salvaAsked=1; avSave(); avOpen('park'); }},
    {id:'cut', q:['Mi fai i capelli?','Do my hair?'], run:()=>np('salvatore', f.gavePettine?'Con questo pettine faccio miracoli. Ma tu hai bisogno di un esorcismo. Usa la brillantina, va.':'Senza pettine? Esci di qui come un porcospino in lavatrice. No.', f.gavePettine?'With this comb I work miracles. But you need an exorcism. Use the gel.':'Without my comb? You\'d leave like a hedgehog out of a washing machine. No.')},
    {id:'gossip', q:['Qualche segreto delle clienti?','Any client secrets?'], when:()=>f.gavePettine, run:()=>np('salvatore','La Contessa si tinge i capelli col vino rosso. Il sindaco si fa il riporto con i peli della schiena. E Gaspare... Gaspare viene qui ogni lunedì e si fa fare un taglio "da corvo". Così lo chiama lui.','The Countess dyes her hair with red wine. The mayor does his comb-over with back hair. And Gaspare... comes every Monday for what he calls a "crow cut".')},
    {id:'poster', q:['Cos\'è lo "Stile \'83"?','What\'s "Style \'83"?'], run:()=>np('salvatore','Il taglio che ho inventato nel 1983, l\'anno in cui ho aperto. Riga in mezzo, basette a punta, nuca a scodella. Elegante come un dirigente della Democrazia Cristiana.','The cut I invented in 1983, the year I opened. Centre parting, pointy sideburns, bowl nape. Elegant as an old party boss.')}
  ]); });
avOn('give:salvatore:pettine',async()=>{ const f=F(); avDel('pettine'); f.gavePettine=1; avSave(); await npcAct('salvatore','cheer',1200);
  await np('salvatore','Il mio pettine! Ti bacerei, ma hai l\'alito di uno che ha dormito in un posacenere.','My comb! I\'d kiss you, but your breath says you slept in an ashtray.');
  await np('salvatore','La parola intera è "Pippi mosce". Non chiedermi perché, l\'ha scelta Ercole il buttafuori, e lui di mosce se ne intende.','The full password is "Floppy Pippi". Don\'t ask why, Ercole the bouncer chose it, and he knows about floppy.');
  await np('salvatore','E prendi questa brillantina extra-forte. Tonino ne compra un litro a settimana. Questa è avanzata, come la tua dignità.','And take this extra-strong gel. Tonino buys a litre a week. This is left over, like your dignity.');
  f.pwd=1; avSave(); avDel('biglietto'); avAdd('brillantina'); avOpen('bisca'); });
avOn('give:salvatore:dentiera',()=>np('salvatore','Una dentiera? Sono un barbiere, non un dentista. E comunque questa ha morso un piccione, si vede.','Dentures? I\'m a barber, not a dentist. And these bit a pigeon, you can tell.'));
avOn('look:chair',()=>me('La poltrona del barbiere. Gira, ma solo se le offri da bere.','The barber chair. It spins, but only if you buy it a drink.'));
avOn('use:chair',async()=>{ await meAct('sit',1500); return np('salvatore','Alzati, che la poltrona è per i clienti paganti. Tu sei un cliente parlante. Peggio.','Get up, the chair is for paying customers. You\'re a talking customer. Worse.'); });
avOn('look:mirror',()=>me(F().slick?'Capelli all\'indietro, lucidi. Sembro un presentatore di quiz degli anni \'80. Uno di quelli arrestati.':'Mi guardo. Lo specchio si gira dall\'altra parte.', F().slick?'Slicked back, shiny. I look like an 80s quiz host. One of the arrested ones.':'I look at myself. The mirror looks away.'));
avOn('look:poster',()=>me('Poster: "STILE \'83 — dal 1983, l\'unico taglio che serve". C\'è la foto di un uomo che sembra il sindaco da giovane. Già brutto.','Poster: "STYLE \'83 — since 1983, the only cut you need". There\'s a photo of a man who looks like the young mayor. Already ugly.'));
avOn('look:pole',()=>me('L\'insegna da barbiere a spirale. Se la fissi troppo vedi il passato. Io ci vedo i debiti.','The spiral barber pole. Stare too long and you see the past. I see my debts.'));
avOn('use:me:brillantina use:mirror:brillantina',async()=>{ const f=F(); if (f.slick) return me('Ne ho già messa abbastanza da friggerci una cotoletta.','I\'ve put on enough to fry a cutlet.'); await meAct('brush',1800); f.slick=1; avSave(); avApplyLook();
  return me('Capelli all\'indietro, lucidi come una Ferrari bagnata. Un piccione ci si è appena specchiato.','Hair slicked back, shiny as a wet Ferrari. A pigeon just checked itself out in it.'); });
/* --- parco --- */
avOn('look:fountain',()=>{ const f=F(); if (f.fished) return me('Acqua, monetine e un piccione che si fa il bidet.','Water, coins and a pigeon taking a bidet.'); return me('Sul fondo luccicano un pettine d\'argento, una dentiera e qualche moneta. Questa fontana ha visto feste.','At the bottom glitter a silver comb, a set of dentures and some coins. This fountain has seen parties.'); });
avOn('take:fountain',()=>me('Le mani lì dentro? Ci fanno il bagno i piccioni. E non solo il bagno. E non solo i piccioni.','Hands in there? Pigeons bathe in it. And not only bathe. And not only pigeons.'));
avOn('use:fountain:retino',async()=>{ const f=F(); if (f.fished) return me('Ho già ripescato tutto quello che valeva. Il resto è biologico.','I\'ve fished out everything of value. The rest is biological.'); await meAct('sweep',2200); f.fished=1; avSave();
  avAdd('pettine'); avAdd('dentiera'); avCoin('fountain');
  return me('Pescati: un pettine d\'argento con inciso "Salvatore", una dentiera che sorride ancora e un Pippi d\'oro. Il preservativo lo lascio ai piccioni.','Caught: a silver comb engraved "Salvatore", dentures still smiling and a golden Pippi. The condom I leave to the pigeons.'); });
avOn('look:pbench',()=>me('La panchina dei vecchietti, dove si giudicano i passanti dal 1960.','The old boys\' bench, where passers-by have been judged since 1960.'));
avOn('use:pbench',async()=>{ await meAct('sit',1800); return me('Mi siedo e giudico un piccione. Ha un\'aria colpevole.','I sit and judge a pigeon. It looks guilty.'); });
avOn('look:gino',()=>me('Gino il giardiniere. Pota le siepi a forma di animali. Sono tutte a forma di sindaco.','Gino the gardener. Trims hedges into animal shapes. They\'re all shaped like the mayor.'));
avOn('talk:gino',async()=>{ await avTalk('gino',[
  {id:'fountain', q:['Cosa c\'è nella fontana?','What\'s in the fountain?'], run:()=>np('gino','Di tutto. Ieri sera Nonna Pina ci ha perso la dentiera mentre... mentre faceva una cosa. Con un uomo. Non chiedermi chi. Ero io.','Everything. Last night Granny Pina lost her dentures in it while... doing a thing. With a man. Don\'t ask who. It was me.')},
  {id:'night', q:['Hai visto qualcosa stanotte?','See anything tonight?'], run:()=>np('gino','Il barbiere Salvatore che correva dietro a un gatto col pettine in bocca. Il gatto aveva il pettine, non Salvatore. Il pettine è finito in fontana.','Salvatore the barber chasing a cat with a comb in its mouth. The cat had the comb, not Salvatore. The comb ended up in the fountain.')},
  {id:'hedges', q:['Perché le siepi sono a forma di sindaco?','Why are the hedges shaped like the mayor?'], run:()=>np('gino','Così i cani ci fanno la pipì sopra. È l\'unica forma di democrazia diretta che abbiamo.','So the dogs pee on them. It\'s the only direct democracy we have.')}
  ]); });
avOn('give:gino:dentiera',()=>np('gino','Non è mia, è di Pina. Io ho ancora tutti i denti: tre.','Not mine, it\'s Pina\'s. I still have all my teeth: three.'));
/* --- bisca --- */
AV_ENTER.bisca={ x:120, before:async()=>{ const f=F(); if (f.inBisca) return true;
    avKick('barber'); await np('ercole','Alt. Parola d\'ordine, bello.','Hold it. Password, pal.');
    const o=await avChoose([['Pippi lisce','Smooth Pippi'],['Pippi mosce','Floppy Pippi'],['Apriti sesamo','Open sesame'],['Sono amico del sindaco','I\'m a friend of the mayor']]);
    if (o!==1){ await np('ercole',['Sbagliato. Torna quando hai un cervello.','Hai visto troppi film. Fuori.','Il sindaco qui non lo può vedere nessuno. Fuori prima che ti stacco le orecchie.'][[0,0,1,2][o]],['Wrong. Come back with a brain.','You\'ve seen too many films. Out.','Nobody here can stand the mayor. Out before I rip your ears off.'][[0,0,1,2][o]]); return false; }
    if (!f.pwd){ await np('ercole','...Giusta. Ma chi te l\'ha detta? Bah, chi se ne frega. Entra.','...Correct. Who told you? Ah, who cares. Get in.'); }
    f.inBisca=1; avSave(); await np('ercole','Entra. E non toccare le fiches di Gina, l\'ultimo che ci ha provato ora le conta con il naso.','Get in. And don\'t touch Gina\'s chips, the last guy who tried now counts them with his nose.'); return true; } };
avOn('look:ercole',()=>me('Ercole il buttafuori. Ha il collo più largo della testa e la testa più vuota del frigo.','Ercole the bouncer. Neck wider than his head, head emptier than my fridge.'));
avOn('talk:ercole',async()=>{ await avTalk('ercole',[
  {id:'tonino', q:['Tonino è qui?','Is Tonino here?'], run:()=>np('ercole','Al tavolo. Ha perso tutto stanotte, pure le mutande. Le ha giocate e le ha perse. Le indossa Gina.','At the table. Lost everything tonight, even his underpants. He bet them and lost. Gina\'s wearing them.')},
  {id:'pwd', q:['Perché "Pippi mosce"?','Why "Floppy Pippi"?'], run:()=>np('ercole','Perché così nessuno la dice ad alta voce. Si vergognano. Geniale, no? L\'ho inventata io. Il cervello ce l\'ho, solo che non lo uso spesso.','So nobody says it out loud. They\'re embarrassed. Genius, right? I made it up. I have a brain, I just don\'t use it often.')}
  ]); });
avOn('look:tonino',()=>me('Tonino il Liscio. Ciuffo lucido, camicia viola, odore di sgombro e brillantina. È lui, il ladro di Peppe.','Slick Tonino. Shiny quiff, purple shirt, smell of mackerel and hair gel. That\'s him, Peppe\'s thief.'));
avOn('talk:tonino',async()=>{ const f=F(); if (!await needBadge('tonino')) return;
  if (f.toninoConf) return np('tonino','Ti ho detto tutto. Il Corvo, la Contessa, il poker. Ora lasciami perdere in pace.','I told you everything. The Crow, the Countess, the poker. Now let me lose in peace.');
  await avTalk('tonino',[
    {id:'ladle', q:['Hai rubato tu il Mestolo d\'Oro.','You stole the Golden Ladle.'], run:async()=>{ await np('tonino','Io? Ho un alibi: stanotte ero qui a perdere soldi. Chiedi a chiunque. Chiedi a Gina, ha vinto lei.','Me? I have an alibi: I was here losing money. Ask anyone. Ask Gina, she won.');
      await np('tonino','Ti dico una cosa: sono un uomo d\'onore. Se mi batti a briscola, ti racconto la verità. Se perdi, mi dai il distintivo e lo vendo al mercatino.','I\'ll tell you what: I\'m a man of honour. Beat me at briscola and I\'ll tell you the truth. Lose and you give me the badge, I\'ll sell it at the market.'); f.toninoDare=1; avSave(); }},
    {id:'play', q:['Giochiamo a briscola.','Let\'s play briscola.'], when:()=>f.toninoDare, run:async()=>{
      const r=await avBriscola('Tonino',1);
      if (r===null) return np('tonino','Pareggio! Come la mia vita: né carne né pesce. Anzi, pesce. Rigiochiamo quando vuoi.','A draw! Like my life: neither here nor there. Rematch whenever.');
      if (!r) return np('tonino','Ahahah! Il distintivo lo tengo io? No dai, scherzavo, è di latta. Riprova, perdente.','Hahaha! Do I keep the badge? Nah, kidding, it\'s tin. Try again, loser.');
      avTrophy('briscola','Hai battuto Tonino a briscola.','Beat Tonino at briscola.');
      await np('tonino','Va bene, va bene. Un uomo d\'onore paga i debiti. Almeno quelli di briscola.','Fine, fine. A man of honour pays his debts. At least the briscola ones.');
      await np('tonino','Sì, l\'ho preso io il Mestolo. Ma su commissione! Un tizio con una maschera da corvo mi ha dato 500 Pippi e questa piuma. Ha detto: "Portalo al Magazzino 7 entro le tre".','Yes, I took the Ladle. But on commission! A guy in a crow mask gave me 500 Pippi and this feather. Said: "Bring it to Warehouse 7 by three".');
      await np('tonino','Solo che prima sono passato qui, e la Contessa mi ha sfidato a poker. Avevo un full. Lei quattro assi. Il Mestolo ora ce l\'ha lei, al privé.','Only I stopped here first, and the Countess challenged me at poker. I had a full house. She had four aces. She has the Ladle now, at the privé.');
      await np('tonino','E se il Corvo scopre che ho perso il suo mestolo... farò la fine di uno sgombro. Aperto in due.','And if the Crow finds out I lost his ladle... I\'ll end up like a mackerel. Split open.');
      f.toninoConf=1; avSave(); avAdd('piuma'); avOpen('prive'); avOpen('disco');
      return me('La piuma del Corvo. Un mandante, un ladro e una giocatrice di poker. Questo mestolo gira più di un pettegolezzo.','The Crow\'s feather. A mastermind, a thief and a poker player. This ladle gets around more than gossip.'); }},
    {id:'fish', q:['Perché puzzi di pesce?','Why do you smell of fish?'], run:()=>np('tonino','Lavoro al porto. Cioè, "lavoro". Diciamo che le casse di pesce si aprono da sole e io passo di lì.','I work at the harbour. Well, "work". Let\'s say fish crates open by themselves and I happen to pass by.')},
    {id:'insult', q:['Quel ciuffo sembra un\'onda di petrolio.','That quiff looks like an oil spill.'], once:true, run:()=>np('tonino','E tu sembri l\'uccello che ci è rimasto incastrato dentro.','And you look like the bird that got stuck in it.')}
  ]); });
avOn('give:tonino:distintivo',()=>np('tonino','Me lo dai davvero? ...Ah no, me lo stai mostrando. Che paura. Sto tremando. Di freddo.','You\'re giving it to me? ...Oh, you\'re showing it. Scary. I\'m shaking. From the cold.'));
avOn('look:gina',()=>me('Gina la Squalo. Ha vinto le mutande di Tonino, la macchina del farmacista e la dentiera di un prete. Nessuno l\'ha mai battuta a briscola.','Gina the Shark. Won Tonino\'s underpants, the pharmacist\'s car and a priest\'s dentures. Nobody has ever beaten her at briscola.'));
avOn('talk:gina',async()=>{ const f=F(); await avTalk('gina',[
  {id:'play', q:['Una partita a briscola, Gina?','Game of briscola, Gina?'], when:()=>!f.ginaBeat, run:async()=>{ await np('gina','Contro di me? Va bene, tesoro. Ma io non regalo niente. Neanche ai funerali.','Against me? Fine, darling. But I give nothing away. Not even at funerals.');
    const r=await avBriscola('Gina',2); if (r!==true) return np('gina','Lo sapevo. Torna quando ti sono cresciuti i peli sullo stomaco.','Knew it. Come back when you\'ve grown some hair on your belly.');
    f.ginaBeat=1; avSave(); avTrophy('gina','Hai battuto Gina la Squalo. Nessuno ci era mai riuscito da sobrio.','Beat Gina the Shark. Nobody ever did it sober.'); try{ LIFE.pippi+=30; saveLife(); }catch(e){}
    return np('gina','...Mi hai battuta. Nessuno mi aveva mai battuta. Prendi questi 30 Pippi e non dirlo a nessuno, o ti trovano nel porto.','...You beat me. Nobody ever beat me. Take these 30 Pippi and tell no one, or they\'ll find you in the harbour.'); }},
  {id:'contessa', q:['Conosci la Contessa?','Do you know the Countess?'], run:()=>np('gina','Quella bara. Bara a poker, bara col marito, bara con la tinta. Ma non ho mai capito come. È per questo che la odio. E la ammiro.','That cheat. Cheats at poker, cheats on her husband, cheats with her dye. But I never figured out how. That\'s why I hate her. And admire her.')}
  ]); });
avOn('look:table',()=>me('Il tavolo verde. Fiches, carte, bicchieri e un dente d\'oro. Di chi, non si sa.','The green table. Chips, cards, glasses and a gold tooth. Whose, nobody knows.'));
avOn('use:table',()=>AV_S['talk:gina']());
avOn('look:slot',()=>me('La slot machine. Due ciliegie e una campana. Come sempre. Si chiama "La Suocera": prende tutto e non dà niente.','The slot machine. Two cherries and a bell. As always. It\'s called "The Mother-in-Law": takes everything, gives nothing.'));
avOn('use:slot',async()=>{ await meAct('play',1800); if (F().ginaBeat && avCoin('slot')) return me('TRE CAMPANE! Esce un Pippi d\'oro. Forse battere Gina mi ha portato fortuna.','THREE BELLS! A golden Pippi comes out. Maybe beating Gina brought me luck.'); return me('Ciliegia, ciliegia, limone. La slot mi ride in faccia. Forse mi serve più fortuna. O battere qualcuno di importante.','Cherry, cherry, lemon. The slot laughs at me. Maybe I need more luck. Or to beat someone important.'); });
avOn('look:rules',()=>me('"REGOLE: 1. Niente bari. 2. Si paga in Pippi. 3. Chi vomita pulisce. 4. Chi muore paga lo stesso."','"RULES: 1. No cheats. 2. Pay in Pippi. 3. You puke, you clean. 4. You die, you still pay."'));
avOn('look:shelf',()=>me('Bottiglie senza etichetta. La bisca fa il suo liquore. Si chiama "Domani No".','Unlabelled bottles. The den makes its own liquor. It\'s called "Not Tomorrow".'));
/* ================= PISTA B: CONTESSA ================= */
/* --- discoteca --- */
avOn('look:djmax',()=>me('DJ Max. Cresta blu, occhiali da sole di notte, cinquantacinque anni portati come un ventenne. Un ventenne messo male.','DJ Max. Blue mohawk, sunglasses at night, fifty-five going on twenty. A rough twenty.'));
avOn('talk:djmax',async()=>{ const f=F(); await avTalk('djmax',[
  {id:'invite', q:['Mi serve un invito per il privé.','I need an invitation to the privé.'], when:()=>!f.invite, run:async()=>{ await np('djmax','Gli inviti li stampo io, ma non li regalo. Stanotte sono di cattivo umore: mi manca il mio vinile, "Italo Disco Bomba 1983". Pezzo unico.','I print the invitations, but I don\'t give them away. I\'m in a mood tonight: my record is missing, "Italo Disco Bomb 1983". One of a kind.');
    await np('djmax','Ce l\'ha Nonna Pina, al karaoke. Lo usa come sottobicchiere. Come sottobicchiere! Riportamelo e l\'invito è tuo.','Granny Pina has it, at the karaoke. She uses it as a coaster. A COASTER! Bring it back and the invitation\'s yours.'); f.djAsked=1; avSave(); avOpen('karaoke'); }},
  {id:'pina', q:['Perché ce l\'ha Pina?','Why does Pina have it?'], when:()=>f.djAsked, run:()=>np('djmax','Ballando la lambada le ho rotto la dentiera con una gomitata. Lei si è presa il disco come risarcimento. Una vecchia con la dentiera rotta è più pericolosa di uno squalo.','Dancing the lambada I broke her dentures with my elbow. She took the record as compensation. An old lady with broken teeth is deadlier than a shark.')},
  {id:'crow', q:['Sai niente del Corvo?','Know anything about the Crow?'], when:()=>f.toninoConf, run:()=>np('djmax','Il Corvo... qualcuno mi ha chiesto di mettere stanotte "Il volo del calabrone" alle tre in punto. Pagato in contanti, piuma inclusa. Non ho chiesto. Non chiedo mai.','The Crow... someone asked me to play "Flight of the Bumblebee" at exactly three tonight. Paid cash, feather included. I didn\'t ask. I never ask.')},
  {id:'music', q:['Che musica fai?','What music do you play?'], run:()=>np('djmax','Solo vinili. La musica digitale è come il sesso col preservativo: funziona, ma senti meno. ...Scusa, ho detto una volgarità? Sono un DJ.','Vinyl only. Digital music is like... well, it works, but you feel less. Sorry, was that rude? I\'m a DJ.')}
  ]); });
avOn('give:djmax:vinile',async()=>{ const f=F(); avDel('vinile'); await npcAct('djmax','dance',1800,'happy');
  await np('djmax','IL MIO BAMBINO! Puzza di birra e di gin, ma è lui. Ha anche un cerchio di umidità perfetto, adesso. Vintage.','MY BABY! Smells of beer and gin, but it\'s him. Has a perfect wet ring now too. Vintage.');
  await np('djmax','Ecco l\'invito per il privé. Ma ricorda: Jacques ti fa entrare solo coi capelli impeccabili. Con quei capelli, nemmeno nel cesso del privé.','Here\'s the privé invitation. But remember: Jacques only lets you in with impeccable hair. With that hair, not even into the privé toilet.');
  f.invite=1; avSave(); avAdd('invito'); });
avOn('look:tony',()=>me('Tony il buttafuori della discoteca. Lascia entrare chiunque: il locale è vuoto da quando hanno aperto un supermercato con le luci più belle.','Tony the disco bouncer. Lets anyone in: the club has been empty since a supermarket opened with nicer lights.'));
avOn('talk:tony',()=>np('tony','Entra pure. Sei il primo cliente da martedì. Quello di martedì era venuto a riparare la luce.','Come on in. You\'re the first customer since Tuesday. Tuesday\'s came to fix the lights.'));
avOn('look:booth',()=>me('La consolle di DJ Max. Piatti, mixer e una foto autografata di un cantante italo-disco morto di overdose di lacca.','DJ Max\'s booth. Decks, mixer and a signed photo of an italo-disco singer who died of a hairspray overdose.'));
avOn('look:floor',()=>me('La pista da ballo. Vuota. Luccica solo il vomito di sabato.','The dance floor. Empty. Only Saturday\'s vomit glitters.'));
avOn('use:floor',async()=>{ await meAct('disco',2600); return me('Ballo da solo. DJ Max mi guarda con compassione. Anche io mi guardo con compassione.','I dance alone. DJ Max looks at me with pity. So do I.'); });
/* --- privé --- */
AV_ENTER.prive={ x:90, before:async()=>{ const f=F(); if (f.inPrive) return true;
    avKick('disco');
    if (!f.invite){ await np('jacques','Monsieur, il privé è solo su invito. E lei non ha l\'invito. E nemmeno la faccia da invito.','Monsieur, the privé is by invitation only. And you have no invitation. Nor the face for one.'); return false; }
    if (!f.slick){ await np('jacques','L\'invito c\'è. Ma con quei capelli? Sembra un nido di gabbiani in una tempesta. Torni impeccabile, monsieur.','The invitation is fine. But that hair? Looks like a seagull nest in a storm. Come back impeccable, monsieur.'); return false; }
    await np('jacques','Oh là là, che ciuffo. E che invito. Prego, monsieur. Non tocchi lo champagne, costa più del suo fegato.','Oh là là, what a quiff. And what an invitation. This way, monsieur. Don\'t touch the champagne, it costs more than your liver.');
    f.inPrive=1; avDel('invito'); avSave(); return true; } };
avOn('look:jacques',()=>me('Jacques. Francese, dice lui. È di Frosinone. Il suo accento francese è un mix tra un gatto strozzato e un notaio.','Jacques. French, he says. He\'s from a town outside Rome. His French accent is a strangled cat crossed with a notary.'));
avOn('talk:jacques',()=>np('jacques','Monsieur è già dentro. Monsieur si diverta. Con moderazione. Che qui le ambulanze non entrano.','Monsieur is already in. Monsieur, enjoy yourself. In moderation. Ambulances don\'t come in here.'));
avOn('look:contessa',()=>me('La Contessa Vanda. Tre mariti sepolti, quattro assi nella manica e un mestolo d\'oro nella borsetta. Lo vedo spuntare.','Countess Vanda. Three husbands buried, four aces up her sleeve and a golden ladle in her handbag. I can see it sticking out.'));
avOn('talk:contessa',async()=>{ const f=F(); if (!await needBadge('contessa')) return;
  if (f.gavePizza) return np('contessa','La pizza era divina. Ora lasciami digerire con eleganza. E con un ruttino aristocratico.','The pizza was divine. Now let me digest elegantly. With an aristocratic burp.');
  await avTalk('contessa',[
    {id:'ladle', q:['Il Mestolo d\'Oro è nella sua borsetta.','The Golden Ladle is in your handbag.'], run:async()=>{ await np('contessa','Vinto onestamente a poker. Quattro assi. Il povero Tonino aveva un full e la faccia di un merluzzo bollito.','Won fair and square at poker. Four aces. Poor Tonino had a full house and the face of a boiled cod.');
      await np('contessa','Te lo do... in cambio di una cosa. Ho una fame da lupa e qui servono solo tartine grandi come unghie. Portami una pizza. Fresca, col basilico vero. Alle tre di notte. Se ci riesci, il mestolo è tuo.','I\'ll give it to you... for something. I\'m starving and here they only serve canapés the size of fingernails. Bring me a pizza. Fresh, with real basil. At 3 a.m. Manage that, and the ladle is yours.');
      f.contessaAsked=1; avSave(); avOpen('pizzeria'); }},
    {id:'cheat', q:['Quattro assi? Lei bara.','Four aces? You cheat.'], run:()=>np('contessa','Barare? Io? Tesoro, io non baro. Io ho talento. Il talento di avere sempre un asso in più di quelli che ci sono nel mazzo.','Cheat? Me? Darling, I don\'t cheat. I have talent. The talent of always having one more ace than the deck contains.')},
    {id:'husbands', q:['Cosa è successo ai suoi mariti?','What happened to your husbands?'], run:()=>np('contessa','Il primo: infarto quando ho rilanciato. Il secondo: infarto quando ho visto. Il terzo: infarto quando ho detto "Lo voglio". Gli uomini sono fragili.','The first: heart attack when I raised. The second: heart attack when I called. The third: heart attack when I said "I do". Men are fragile.')},
    {id:'crow', q:['Conosce il Corvo?','Do you know the Crow?'], when:()=>f.toninoConf, run:()=>np('contessa','Il Corvo? Un vecchio corteggiatore, forse. Mi mandava piume nere invece delle rose. Romantico. Ma puzzava di risotto.','The Crow? An old suitor, maybe. Sent me black feathers instead of roses. Romantic. But he smelled of risotto.')},
    {id:'flirt', q:['Lei è bellissima, Contessa.','You\'re gorgeous, Countess.'], once:true, run:()=>np('contessa','Lo so, tesoro. E tu sei... vivo. È già qualcosa. Il mio terzo marito non lo era nemmeno da vivo.','I know, darling. And you\'re... alive. That\'s something. My third husband wasn\'t, even when alive.')}
  ]); });
avOn('give:contessa:pizza',async()=>{ const f=F(); avDel('pizza'); f.gavePizza=1; avSave(); await npcAct('contessa','eat',2000);
  await np('contessa','Mmmh... il basilico, la legna, il cornicione... Totò è un artista. Un artista sudato, ma un artista.','Mmmh... the basil, the wood fire, the crust... Totò is an artist. A sweaty artist, but an artist.');
  await np('contessa','Un patto è un patto. Ecco il tuo mestolo, tesoro. Stranamente leggero per essere oro. Ma io l\'oro lo riconosco solo sui mariti morti.','A deal\'s a deal. Here\'s your ladle, darling. Strangely light for gold. But I only recognise gold on dead husbands.');
  avAdd('mestolo'); return me('Il Mestolo d\'Oro! ...Leggero davvero. Mi conviene guardarlo bene prima di portarlo al sindaco.','The Golden Ladle! ...Really light. I\'d better take a good look before bringing it to the mayor.'); });
avOn('give:contessa:fiori',()=>np('contessa','Fiori di cimitero? Che pensiero carino. Li metto sulla tomba del secondo marito.','Cemetery flowers? How sweet. I\'ll put them on my second husband\'s grave.'));
avOn('look:vsofa',()=>me('Divanetto di velluto. Ha visto cose che voglio dimenticare senza averle viste.','Velvet sofa. It\'s seen things I want to forget without having seen them.'));
avOn('use:vsofa',async()=>{ await meAct('sit',1500); return np('jacques','Monsieur, quel divano costa più di casa sua. Si alzi. Con delicatezza.','Monsieur, that sofa costs more than your house. Get up. Gently.'); });
avOn('look:champagne take:champagne',()=>me('Champagne a 400 Pippi la bottiglia. Lo bevo con gli occhi. Gli occhi si ubriacano.','Champagne at 400 Pippi a bottle. I drink it with my eyes. My eyes get drunk.'));
avOn('look:chandelier',()=>me('Un lampadario di cristallo. Se cade, addio Contessa. Ci penso un attimo di troppo.','A crystal chandelier. If it fell, bye Countess. I think about it a moment too long.'));
/* --- pizzeria --- */
avOn('look:toto',()=>me('Totò il pizzaiolo. Pizzaiolo da tre generazioni. La pancia da quattro.','Totò the pizza man. Pizza maker for three generations. The belly for four.'));
avOn('talk:toto',async()=>{ const f=F(); await avTalk('toto',[
  {id:'pizza', q:['Una pizza per la Contessa, adesso.','A pizza for the Countess, right now.'], when:()=>f.contessaAsked && !f.pizzaDone, run:async()=>{
    if (!f.totoWood){ await np('toto','Alle tre di notte? Il forno è spento e la legna è finita. E il basilico l\'ha mangiato il gatto. Senza legna e senza basilico, niente pizza. È una questione d\'onore.','At 3 a.m.? The oven\'s out and the firewood\'s gone. And the cat ate the basil. No wood, no basil, no pizza. It\'s a matter of honour.');
      await np('toto','Legna buona c\'è nel bosco, dove sta quello svitato di Rino. Il basilico... ce l\'avrai in giardino, no? Tutti hanno il basilico, anche gli assassini.','Good wood in the woods, where that nutter Rino lives. Basil... you\'ve got some in the garden, right? Everyone has basil, even murderers.'); f.totoWood=1; avSave(); avOpen('woods'); return; }
    return np('toto',`Mi servono ancora: ${f.gaveWood?'':'legna '}${f.gaveBasil?'':'basilico'}. Non posso fare miracoli. Solo pizze.`,`I still need: ${f.gaveWood?'':'firewood '}${f.gaveBasil?'':'basil'}. I can\'t do miracles. Only pizzas.`); }},
  {id:'life', q:['Com\'è fare il pizzaiolo?','What\'s it like being a pizza man?'], run:()=>np('toto','Quarant\'anni davanti a un forno a 450 gradi. Ho perso le sopracciglia nel 1992 e la moglie nel 1995. Le sopracciglia mi mancano.','Forty years in front of a 450-degree oven. Lost my eyebrows in 1992 and my wife in 1995. I miss the eyebrows.')},
  {id:'crow', q:['Il Corvo ti dice qualcosa?','Does the Crow ring a bell?'], when:()=>f.toninoConf, run:()=>np('toto','Corvo... ogni anno alla Sagra c\'è qualcuno che mangia tre piatti di risotto e se ne va senza pagare. Il sindaco dice che è "un ospite d\'onore". Non l\'ho mai visto in faccia.','Crow... every year at the Festival someone eats three plates of risotto and leaves without paying. The mayor calls him "a guest of honour". Never saw his face.')}
  ]); });
const totoCheck=async()=>{ const f=F(); if (f.gaveWood && f.gaveBasil && !f.pizzaDone){ await npcAct('toto','cook',2800); f.pizzaDone=1; avSave(); avAdd('pizza'); await np('toto','Ecco: margherita con basilico fresco e legna del bosco. Dille che l\'ha fatta Totò, con amore e sudore. Soprattutto sudore.','Here: margherita with fresh basil and wood from the woods. Tell her Totò made it, with love and sweat. Mostly sweat.'); } };
avOn('give:toto:legna',async()=>{ const f=F(); avDel('legna'); f.gaveWood=1; avSave(); await np('toto','Legna buona! Secca, profumata. Questo era un albero di carattere.','Good wood! Dry, fragrant. This was a tree with character.'); return totoCheck(); });
avOn('give:toto:basilico',async()=>{ const f=F(); avDel('basilico'); f.gaveBasil=1; avSave(); await np('toto','Basilico vero! Lo annuso e mi viene da piangere. Anche per la cipolla che sto tagliando, ma soprattutto per il basilico.','Real basil! I smell it and want to cry. Also because of the onion I\'m cutting, but mostly the basil.'); return totoCheck(); });
avOn('look:oven',()=>me(F().pizzaDone?'Il forno acceso, finalmente. Dentro, la cenere vecchia è stata spinta in un angolo.':'Il forno a legna. Spento e freddo come il cuore della Contessa.', F().pizzaDone?'The oven, lit at last. The old ash has been pushed into a corner.':'The wood oven. Out and cold as the Countess\'s heart.'));
avOn('open:oven take:oven',async()=>{ if (!F().pizzaDone) return me('Ci frugo dentro? Ci sono vent\'anni di cenere. Magari quando è acceso, che si vede meglio. No, aspetta, quando è acceso brucia.','Dig inside? Twenty years of ash. Maybe when it\'s lit and I can see. No wait, then it burns.'); await meAct('squat',1000); if (avCoin('oven')) return me('Nella cenere spostata, un Pippi d\'oro, mezzo fuso. Vale lo stesso.','In the pushed-aside ash, a golden Pippi, half melted. Still counts.'); return me('Solo cenere. E una sopracciglia di Totò, del 1992.','Just ash. And one of Totò\'s eyebrows, from 1992.'); });
avOn('look:ptable',()=>me('Un tavolo apparecchiato. C\'è una forchetta piegata: qualcuno ha protestato per il conto.','A laid table. There\'s a bent fork: someone complained about the bill.'));
avOn('look:menu',()=>me('Il menù. "Pizza del Sindaco: tutto a carico dei cittadini." "Pizza Suocera: piccante e indigesta."','The menu. "Mayor\'s Pizza: all on the taxpayer." "Mother-in-Law Pizza: spicy and indigestible."'));
/* --- il mestolo finto --- */
avOn('look:mestolo',()=>me('Il Mestolo d\'Oro. Luccica, ma è leggerissimo. E se lo stringo... fa crac. L\'oro non fa crac.','The Golden Ladle. Shiny, but so light. And when I squeeze it... it cracks. Gold doesn\'t crack.'));
avOn('use:mestolo:lente use:lente:mestolo',async()=>{ const f=F(); await meAct('look',1500); f.fakeKnown=1; avSave(); avSwap('mestolo','cioccolato'); avAdd('etichetta'); avOpen('porto');
  await me('Con la lente vedo le pieghe della stagnola. È CIOCCOLATO. Cioccolato fondente rivestito di stagnola dorata!','Through the glass I see the foil creases. It\'s CHOCOLATE. Dark chocolate wrapped in gold foil!');
  return me('Sotto la stagnola c\'è un\'etichetta: "Magazzino 7 — Porto — lotto 50 pz". Cinquanta mestoli finti. La Contessa è stata fregata. Tonino pure. E qualcuno ride.','Under the foil there\'s a label: "Warehouse 7 — Harbour — batch of 50". Fifty fake ladles. The Countess got conned. Tonino too. And someone is laughing.'); });
avOn('use:me:cioccolato use:me:mestolo',()=>me('Mangiarmi la prova? Ho fame, ma non sono così coglione. Quasi.','Eat the evidence? I\'m hungry, but not that stupid. Almost.'));
avOn('look:cioccolato',()=>me('Un mestolo di cioccolato fondente nella stagnola dorata. Una truffa deliziosa.','A dark-chocolate ladle in gold foil. A delicious scam.'));
avOn('look:etichetta',()=>me('"Magazzino 7 — Porto — lotto 50 pz". Qualcuno ha fatto produrre cinquanta mestoli di cioccolato.','"Warehouse 7 — Harbour — batch of 50". Someone had fifty chocolate ladles made.'));
avOn('look:piuma',()=>me('Una piuma nera, lucida, profumata. Profuma di... risotto allo zafferano. Che cazzo.','A glossy black feather, scented. It smells of... saffron risotto. What the hell.'));
avOn('give:sindaco:mestolo',async()=>{ const f=F(); avDel('mestolo'); f.fakeKnown=1; avSave();
  await np('sindaco','IL MESTOLO! Fammelo vedere... mmm, è leggero. Lo assaggio, per tradizione.','THE LADLE! Let me see... hmm, it\'s light. I\'ll taste it, by tradition.'); await npcAct('sindaco','eat',1600);
  await np('sindaco','È CIOCCOLATO! Fondente! Buono, eh, ma è CIOCCOLATO! Mi prendi per il culo?!','It\'s CHOCOLATE! Dark! Tasty, sure, but CHOCOLATE! Are you taking the piss?!');
  await np('peppe','Ne avanza un pezzo? Alla mia età il cioccolato è l\'unico piacere rimasto. Quello e i funerali degli altri.','Any left? At my age chocolate is the only pleasure left. That and other people\'s funerals.');
  avAdd('etichetta'); avOpen('porto'); return me('Sotto la stagnola rimasta c\'è un\'etichetta: "Magazzino 7 — Porto". Qualcuno ha fatto cinquanta mestoli finti.','Under the leftover foil there\'s a label: "Warehouse 7 — Harbour". Someone made fifty fake ladles.'); });
avOn('give:sindaco:cioccolato',()=>np('sindaco','Me lo ha già detto mezzo paese che è cioccolato. Portami quello VERO, cretino.','Half the town already told me it\'s chocolate. Bring me the REAL one, idiot.'));
avOn('give:peppe:cioccolato',async()=>{ avDel('cioccolato'); await npcAct('peppe','eat',1600); return np('peppe','Fondente al 70%. Come la grappa di tuo nonno. Grazie, giovane. Ora posso morire. Domani, però.','70% dark. Like your grandpa\'s grappa. Thanks, youngster. Now I can die. Tomorrow, though.'); });
/* ================= PISTA C: GASPARE ================= */
avOn('look:warehouse',()=>me(F().doorOpen?'Il Magazzino 7, aperto. Dentro: casse e casse di mestoli di cioccolato. Puzza di cacao e di sgombro.':'Il Magazzino 7. Lucchetto grosso come la mia testa. Dalla fessura esce odore di cacao. E di pesce. Insieme. Che schifo.', F().doorOpen?'Warehouse 7, open. Inside: crates and crates of chocolate ladles. Reeks of cocoa and mackerel.':'Warehouse 7. A padlock as big as my head. Cocoa smell comes through the crack. And fish. Together. Gross.'));
avOn('open:warehouse use:warehouse',async()=>{ const f=F(); if (!f.doorOpen) return me('Chiuso a chiave. Spallata? L\'ultima volta che ho preso a spallate una porta era di vetro. Ho ancora i punti.','Locked. Shoulder-barge it? Last time I did that the door was glass. Still have the stitches.');
  if (!f.receipt){ f.receipt=1; avSave(); avAdd('ricevuta'); avOpen('municipio'); return me('Frugo tra le casse... una ricevuta!','I rummage through the crates... a receipt!'); }
  return me('Solo cioccolato. Tanto. Troppo. Ok, ne mangio uno. Due. Basta.','Just chocolate. Lots. Too much. Fine, I\'ll eat one. Two. Stop.'); });
avOn('use:warehouse:chiave',async()=>{ const f=F(); await meAct('squat',1200); f.doorOpen=1; avDel('chiave'); avSave(); drawRoom('porto'); avSpawn('porto');
  await me('Clac! Si apre. Cacao e sgombro, un profumo che non auguro a nessuno. Neanche alla suocera. Vabbè, alla suocera sì.','Clack! It opens. Cocoa and mackerel, a smell I wouldn\'t wish on anyone. Except my mother-in-law.');
  await me('Cinquanta mestoli di cioccolato, uno per cassa. E in cima, una ricevuta.','Fifty chocolate ladles, one per crate. And on top, a receipt.');
  f.receipt=1; avSave(); avAdd('ricevuta'); avOpen('municipio');
  return me('"Ordine: 50 mestoli di cioccolato dorato per la Sagra. Il VERO resta nella mia cassaforte in Municipio. Al Corvo diremo che è stato rubato. — G."','"Order: 50 gold-foil chocolate ladles for the Festival. The REAL one stays in my safe at the Town Hall. We\'ll tell the Crow it was stolen. — G."'); });
avOn('look:ricevuta',()=>me('"50 mestoli di cioccolato dorato. Il VERO nella mia cassaforte in Municipio. Al Corvo diremo che è stato rubato. — G." G. come Gaspare. O come Gino. No, Gino non sa scrivere.','"50 gold-foil chocolate ladles. The REAL one in my safe at the Town Hall. We\'ll tell the Crow it was stolen. — G." G for Gaspare. Or Gino. No, Gino can\'t write.'));
avOn('look:crates',()=>me('Casse con scritto "PESCE". Anche il pesce dentro ha scritto "PESCE". Qui sono precisi.','Crates marked "FISH". Even the fish inside are marked "FISH". Very precise here.'));
avOn('open:crates',async()=>{ await meAct('squat',1000); if (avCoin('crates')) return me('Tra gli sgombri, un Pippi d\'oro. Puzzerà di pesce per sempre. Come i soldi del sindaco.','Among the mackerel, a golden Pippi. It\'ll smell of fish forever. Like the mayor\'s money.'); return me('Sgombri. Mi fissano tutti. Hanno lo stesso sguardo di Tonino.','Mackerel. They all stare at me. Same look as Tonino.'); });
avOn('look:boat',()=>me('"Baffo II", la barca di Baffo. La "Baffo I" l\'ha affondata la Guardia di Finanza nel 2007, con dentro tre nonne.','"Baffo II", Baffo\'s boat. The tax police sank the "Baffo I" in 2007, with three grannies aboard.'));
avOn('use:boat',()=>me('Rubare la barca di Baffo? Così poi galleggio io. A faccia in giù.','Steal Baffo\'s boat? Then I\'d be the one floating. Face down.'));
avOn('look:lamp',()=>me('Un lampione. I gabbiani lo usano come bagno pubblico. Il lampione ha smesso di lamentarsi.','A lamp post. The seagulls use it as a public toilet. The lamp post stopped complaining.'));
avOn('look:ciccio',()=>me('Ciccio il pescatore. Ha la barba piena di sale, di squame e di segreti. Soprattutto di squame.','Ciccio the fisherman. His beard is full of salt, scales and secrets. Mostly scales.'));
avOn('talk:ciccio',async()=>{ const f=F(); await avTalk('ciccio',[
  {id:'warehouse', q:['Di chi è il Magazzino 7?','Whose is Warehouse 7?'], run:async()=>{ await np('ciccio','Dell\'Assessore Gaspare. Dice che ci tiene le reti del comune. Ma da quando le reti puzzano di cioccolato? E da quando il comune ha delle reti?','Councillor Gaspare\'s. Says he keeps the council\'s nets in it. Since when do nets smell of chocolate? Since when does the council have nets?');
    await np('ciccio','Le chiavi di tutto il porto le ha Marisa, la guardiana del faro. Ma non regala niente a nessuno: è sveglia da tre notti e morde.','Marisa the lighthouse keeper has keys to the whole harbour. But she gives nothing away: she\'s been awake three nights and she bites.'); f.ciccio=1; avSave(); avOpen('faro'); }},
  {id:'gaspare', q:['Hai visto Gaspare stanotte?','Did you see Gaspare tonight?'], run:()=>np('ciccio','Ha detto a tutti che stanotte era al porto "a controllare le reti". Io stanotte ero al porto. Le reti c\'erano. Gaspare no.','He told everyone he was at the harbour tonight "checking the nets". I was at the harbour tonight. The nets were there. Gaspare wasn\'t.')},
  {id:'life', q:['Pescato qualcosa stanotte?','Caught anything tonight?'], run:()=>np('ciccio','Una scarpa, una ruota e la dentiera di mio cognato. Annata buona. L\'anno scorso avevo pescato mio cognato.','A shoe, a wheel and my brother-in-law\'s dentures. Good year. Last year I caught my brother-in-law.')},
  {id:'grandpa', q:['Sai niente di un\'isola e di un tesoro?','Know anything about an island and a treasure?'], when:()=>avHas('tessera'), run:()=>np('ciccio','L\'Isola dei Pippi? È una leggenda dei pescatori. Dicono che chi ci va torna ricco o non torna. Mio nonno ci è andato. Non è tornato. Ma ci ha mandato una cartolina: "Qui si sta benissimo".','Pippi Island? A fishermen\'s legend. They say whoever goes comes back rich or not at all. My grandpa went. Never came back. But he sent a postcard: "Lovely here".')}
  ]); });
avOn('look:marisa',()=>me('Marisa, la guardiana del faro. Occhiaie fino alle ginocchia e quindici gatti. O sedici. Contarli è impossibile, si muovono.','Marisa, the lighthouse keeper. Eye bags down to her knees and fifteen cats. Or sixteen. Impossible to count, they move.'));
avOn('talk:marisa',async()=>{ const f=F();
  if (f.gaveCoffee) return np('marisa','Grazie ancora per il caffè. Ora vai a rompere le palle all\'Assessore. Rompigliele forte.','Thanks again for the coffee. Now go bust the Councillor\'s balls. Bust them hard.');
  await avTalk('marisa',[
    {id:'keys', q:['Mi servono le chiavi del Magazzino 7.','I need the Warehouse 7 key.'], run:async()=>{ await np('marisa','Sono sveglia da tre notti. Il faro non si spegne da solo, e il comune non mi manda il cambio da otto anni. Grazie, Assessore Gaspare.','I\'ve been awake three nights. The lighthouse doesn\'t switch itself off, and the council hasn\'t sent a relief in eight years. Thanks, Councillor Gaspare.');
      await np('marisa','Portami un caffè. CALDO. Bollente. Che mi ustioni la lingua. E ti do quello che vuoi, tranne i gatti.','Bring me a coffee. HOT. Scalding. So it burns my tongue. And I\'ll give you anything you want, except the cats.'); f.marisaAsked=1; avSave(); }},
    {id:'see', q:['Cosa si vede da lassù di notte?','What can you see up there at night?'], run:()=>np('marisa','Vedo tutto. Ma la memoria mi torna solo con la caffeina. Prima del caffè non ricordo neanche come si chiamano i gatti. Si chiamano tutti Gatto.','I see everything. But my memory only comes back with caffeine. Before coffee I can\'t even remember the cats\' names. They\'re all called Cat.')},
    {id:'cats', q:['Perché così tanti gatti?','Why so many cats?'], run:()=>np('marisa','Perché i gatti non parlano, non votano e non fanno gli assessori. Sono superiori a tutti voi.','Because cats don\'t talk, don\'t vote and don\'t become councillors. They\'re superior to all of you.')}
  ]); });
avOn('give:marisa:moka',()=>np('marisa','Una moka vuota? Mi stai prendendo per il culo? Pieno, caldo, bollente! Cosa non è chiaro?','An empty pot? Are you taking the piss? Full, hot, scalding! What\'s unclear?'));
avOn('give:marisa:caffe',async()=>{ const f=F(); avDel('caffe'); f.gaveCoffee=1; avSave(); await npcAct('marisa','drink',2000);
  await np('marisa','Ahhh. Sono di nuovo una persona. Più o meno. Una persona con un pessimo carattere, ma una persona.','Ahhh. I\'m a person again. Roughly. A person with a terrible temper, but a person.');
  await np('marisa','Ecco la chiave del Magazzino 7. E ora che ho il cervello acceso: stanotte alle due ho visto l\'Assessore Gaspare uscire dal magazzino con qualcosa che brillava sotto il braccio.','Here\'s the Warehouse 7 key. And now my brain\'s on: at two tonight I saw Councillor Gaspare leave the warehouse with something shiny under his arm.');
  await np('marisa','È andato dritto in Municipio. Un assessore al lavoro alle due di notte. In trent\'anni non ne ho mai visto uno lavorare neanche alle due di pomeriggio.','He went straight to the Town Hall. A councillor at work at 2 a.m. In thirty years I\'ve never seen one work at 2 p.m.');
  f.marisaSaw=1; avSave(); avAdd('chiave'); return me('Lo scrivo sul taccuino. Testimonianza di Marisa: Gaspare, ore 2, dal magazzino al municipio, con qualcosa di luccicante.','I write it in the notebook. Marisa\'s testimony: Gaspare, 2 a.m., warehouse to town hall, carrying something shiny.'); });
avOn('look:lhdoor',()=>me('La porta del faro. Cartello: "NON DISTURBARE. MORDO. — Marisa". E sotto, più piccolo: "Anche i gatti."','The lighthouse door. Sign: "DO NOT DISTURB. I BITE. — Marisa". Below, smaller: "So do the cats."'));
avOn('open:lhdoor',()=>np('marisa','Lì dentro non entra nessuno. Neanche io, quando ho le mie cose. Cioè, quando ho le mie cose da fare.','Nobody goes in there. Not even me, when I\'m in a mood.'));
avOn('look:lantern',()=>me('La lanterna gira e illumina il mare. E ogni tanto la finestra del bagno del sindaco. Marisa dice che è il momento più comico della notte.','The lantern turns and lights the sea. And now and then the mayor\'s bathroom window. Marisa says it\'s the funniest moment of the night.'));
avOn('look:hut',()=>me('La casetta di Marisa. Quindici gatti alla finestra. Sedici. Diciassette, uno è appena uscito dal camino.','Marisa\'s hut. Fifteen cats at the window. Sixteen. Seventeen, one just came out of the chimney.'));
avOn('look:buoy take:buoy',()=>me('Un salvagente. Lo lascio qui per qualcuno più sfortunato di me. Ce ne sono pochi, ma ci sono.','A life buoy. I\'ll leave it for someone unluckier than me. Few, but they exist.'));
avOn('look:rocks',()=>me('Scogli. Uno ha la forma della faccia del sindaco. Ugualmente duro.','Rocks. One looks like the mayor\'s face. Equally thick.'));
/* --- municipio --- */
AV_ENTER.municipio={ x:70, before:async()=>{ const f=F(); if (f.inMuni) return true;
    avKick('piazza'); await np('gennaro','Chiuso! È notte! Qui entrano solo le autorità! Le autorità vere, non i volontari col distintivo di latta!','Closed! It\'s night! Authorities only! Real ones, not volunteers with tin badges!');
    if (!f.disguise){ await me('Mi serve un\'aria più... autorevole. Tipo quella di uno che fa paura a un impiegato comunale. Chi fa paura agli impiegati comunali?','I need to look more... authoritative. Like someone who scares a council clerk. Who scares council clerks?'); return false; }
    if (!f.trench){ await np('gennaro','Coi baffi e in pigiama? Sembri un ispettore della Finanza ubriaco. ...Che poi, sono i peggiori. Ma no, in pigiama no.','Moustache and pyjamas? You look like a drunk tax inspector. ...Who are the worst. But no, not in pyjamas.'); return false; }
    await np('gennaro','...Impermeabile, baffi, sguardo da bastardo... la FINANZA?! Prego, prego, Ispettore! Io timbro il cartellino e basta, non so niente, non ho visto niente, ho tre figli!','...Trench coat, moustache, bastard stare... the TAX POLICE?! Come in, Inspector! I just clock in, I know nothing, saw nothing, I have three kids!');
    f.inMuni=1; avSave(); return true; } };
avOn('use:me:baffi',async()=>{ const f=F(); if (f.disguise) return me('Ho già i baffi. Con altri due sembro un tricheco in crisi.','I already have a moustache. Two more and I\'m a walrus in crisis.'); await meAct('brush',1300); f.disguise=1; avSave(); avApplyLook();
  return me('Baffi finti, sguardo severo, voce da accertamento fiscale. Se mi guardo allo specchio mi viene voglia di fare la dichiarazione dei redditi.','Fake moustache, stern look, audit voice. If I look in the mirror I feel like filing my tax return.'); });
avOn('look:gennaro',()=>me('Gennaro l\'usciere. Dorme in piedi da vent\'anni. Si sveglia solo per timbrare e per il pranzo.','Gennaro the porter. Has slept standing up for twenty years. Wakes only to clock in and for lunch.'));
avOn('talk:gennaro',async()=>{ const f=F(); await avTalk('gennaro',[
  {id:'gaspare', q:['L\'Assessore era qui stanotte?','Was the Councillor here tonight?'], run:()=>np('gennaro','Signor Ispettore, alle due è entrato con un sacco e un sorriso. È uscito senza sacco e con un sorriso più grande. Io non ho visto niente. Ho tre figli.','Inspector, sir, at two he came in with a sack and a smile. Left without the sack and with a bigger smile. I saw nothing. I have three kids.')},
  {id:'kids', q:['Tre figli?','Three kids?'], run:()=>np('gennaro','Uno fa l\'assessore, uno fa il vigile, uno fa il bidello. Tutti in comune. È una tradizione di famiglia, si chiama raccomandazione.','One\'s a councillor, one\'s a traffic warden, one\'s a janitor. All at the council. Family tradition. It\'s called nepotism.')}
  ]); });
avOn('look:gaspare',()=>me('L\'Assessore Gaspare. Sorriso da dentifricio, pizzetto da diavolo dei poveri, occhi da gatto che ha mangiato il canarino e il proprietario.','Councillor Gaspare. Toothpaste smile, discount-devil goatee, eyes of a cat that ate the canary and the owner.'));
const GASPARE_LIES=[
  {say:['Stanotte ero a casa a dormire, come ogni buon cristiano.','Tonight I was home asleep, like every good Christian.'], press:['Dormivo profondamente. Ho il sonno pesante. Come la coscienza: pesante ma pulita.','I slept like a log. Heavy sleeper. Like my conscience: heavy but clean.'], ok:i=>i==='taccuino' && F().marisaSaw, win:['Marisa ti ha visto alle due uscire dal Magazzino 7 con qualcosa di luccicante, e Gennaro ti ha visto entrare qui. Ce l\'ho sul taccuino.','Marisa saw you at two leaving Warehouse 7 with something shiny, and Gennaro saw you come in here. It\'s in my notebook.'], after:['Ehm... sonnambulismo! Soffro di sonnambulismo assessorile!','Er... sleepwalking! I suffer from councillor sleepwalking!']},
  {say:['Il Magazzino 7? Mai sentito. Io non ho magazzini, ho solo ideali.','Warehouse 7? Never heard of it. I don\'t have warehouses, only ideals.'], press:['Ideali grandi, eh. Ma magazzini no. Neanche un ripostiglio.','Big ideals. But no warehouses. Not even a cupboard.'], ok:'etichetta', win:['Allora perché i mestoli finti hanno l\'etichetta "Magazzino 7"? E Ciccio dice che il magazzino è tuo.','Then why do the fake ladles say "Warehouse 7"? And Ciccio says the warehouse is yours.'], after:['Ciccio è un pescatore. I pescatori mentono, è risaputo. Raccontano pesci enormi...','Ciccio\'s a fisherman. Fishermen lie, everyone knows. They tell of huge fish...']},
  {say:['E comunque io il cioccolato non lo sopporto. Sono diabetico. Il cioccolato per me è veleno.','Besides, I can\'t stand chocolate. I\'m diabetic. Chocolate is poison to me.'], press:['Veleno, ti dico. Solo a guardarlo mi sale la glicemia.','Poison, I tell you. Just looking at it raises my blood sugar.'], ok:'ricevuta', win:['Strano, per un diabetico, ordinare cinquanta mestoli di cioccolato. Firmato "G." E qui c\'è scritto che il vero è nella tua cassaforte.','Odd for a diabetic to order fifty chocolate ladles. Signed "G." And it says the real one is in your safe.'], after:['G... G può essere chiunque! Gino! Gennaro! Gesù!','G... G could be anyone! Gino! Gennaro! Jesus!']},
  {say:['E poi lavoro da solo. Non ho complici. Sono un uomo libero, come un uccellino.','And I work alone. No accomplices. I\'m a free man, like a little bird.'], press:['Un uccellino libero. Un passerotto. Cip cip.','A free little bird. A sparrow. Tweet tweet.'], ok:'piuma', win:['Un uccellino? Tipo un corvo? Tonino ha avuto questa piuma dal Corvo. E il barbiere dice che ogni lunedì ti fai fare il "taglio da corvo".','A little bird? Like a crow? Tonino got this feather from the Crow. And the barber says every Monday you get a "crow cut".'], after:['...Va bene. VA BENE! Lavoravo per il Corvo! Ma volevo fregarlo! Volevo tenermi il mestolo vero e dargli quello di cioccolato!','...Fine. FINE! I worked for the Crow! But I wanted to cheat him! Keep the real ladle and give him the chocolate one!']}
];
avOn('talk:gaspare',async()=>{ const f=F(); if (!await needBadge('gaspare')) return;
  if (!f.gaspareTalk){ f.gaspareTalk=1; avSave(); await np('gaspare','Un ispettore della Finanza alle tre di notte! Che onore. I miei conti sono in ordine, glielo giuro sulla tomba di mia madre. Che è viva, ma ci tengo lo stesso.','A tax inspector at 3 a.m.! What an honour. My accounts are in order, I swear on my mother\'s grave. She\'s alive, but still.'); }
  const o=await avChoose([['Facciamo due domande, Assessore.','Let\'s have a little chat, Councillor.'],['Bei baffi i miei, eh?','Nice moustache, eh?'],['Niente, passavo.','Nothing, just passing.']]);
  if (o===1) return np('gaspare','Bellissimi. Sembrano finti. Ah, ah. ...Sono finti?','Lovely. They look fake. Ha ha. ...Are they fake?');
  if (o===2) return;
  await me('Dov\'eri stanotte, Gaspare? E dov\'è il Mestolo d\'Oro?','Where were you tonight, Gaspare? And where is the Golden Ladle?');
  const ok=await avInterrogate('gaspare', GASPARE_LIES);
  if (!ok) return np('gaspare','Ispettore, mi sembra stanco. Torni quando ha prove vere. Io intanto mi faccio una camomilla. Corretta.','Inspector, you look tired. Come back with real evidence. Meanwhile I\'ll have a chamomile. Spiked.');
  avTrophy('gaspare','Interrogatorio da sbirro vero.','Interrogation like a real cop.');
  await np('gaspare','Il Corvo mi aveva ordinato di far rubare il mestolo e portarglielo. Io ho fatto fare i mestoli di cioccolato, ho dato quello finto a Tonino e ho tenuto il vero. Doppio gioco! Geniale!','The Crow ordered me to have the ladle stolen and brought to him. I made the chocolate ones, gave a fake to Tonino and kept the real one. Double cross! Genius!');
  await np('gaspare','Ma se il Corvo lo scopre... no. NO. Non mi prenderete! Né voi né lui!','But if the Crow finds out... no. NO. You won\'t catch me! Not you, not him!');
  const n=npcOf('gaspare'); if (n){ n.keep=1; npcPose(n,'run','scared'); await npcWalk(n, 560); removeNPC(n); AV.npcs=AV.npcs.filter(x=>x!==n); }
  f.gaspareGone=1; avSave();
  await np('gennaro','È saltato dalla finestra! Primo piano! È atterrato nei cassonetti dell\'umido! Signor Ispettore, io non ho visto niente, ho tre figli!','He jumped out the window! First floor! Landed in the compost bins! Inspector, I saw nothing, I have three kids!');
  return me('Nei cassonetti dell\'umido. Il posto giusto per lui. Ora la scrivania è libera, e anche la cassaforte.','In the compost bins. Right where he belongs. Now the desk is free, and so is the safe.'); });
avOn('give:gaspare:ricevuta give:gaspare:piuma give:gaspare:etichetta give:gaspare:taccuino',()=>me('Le prove vanno presentate al momento giusto, mentre mente. Prima facciamolo parlare.','Evidence must be shown at the right moment, while he lies. Let him talk first.'));
avOn('look:desk',()=>me(F().gaspareGone?'Sulla scrivania, un post-it: "Combinazione cassaforte = l\'anno del taglio di Salvatore. NON DIRLO A NESSUNO. Neanche al Corvo."':'La scrivania dell\'Assessore. C\'è un post-it, ma lui ci tiene sopra il gomito. Sudato.', F().gaspareGone?'On the desk, a post-it: "Safe combination = the year of Salvatore\'s haircut. TELL NO ONE. Not even the Crow."':'The Councillor\'s desk. There\'s a post-it, but his sweaty elbow is on it.'));
avOn('open:desk',()=>me(F().gaspareGone?'Nei cassetti: caramelle per diabetici (mai aperte), una maschera da corvo di carnevale e una foto del sindaco con le corna disegnate. Questo almeno mi è simpatico.':'Con lui seduto lì? Mi stacca la mano.', F().gaspareGone?'In the drawers: diabetic sweets (never opened), a carnival crow mask and a photo of the mayor with horns drawn on. That I like.':'With him sitting there? He\'d bite my hand off.'));
avOn('look:safe',()=>me(F().safeOpen?'La cassaforte, aperta e vuota. Come le casse del comune.':'Una cassaforte a combinazione, quattro cifre. Massiccia. Contiene i segreti del comune o i suoi panini.', F().safeOpen?'The safe, open and empty. Like the council coffers.':'A four-digit combination safe. Massive. Holds the council\'s secrets or its sandwiches.'));
avOn('open:safe use:safe',async()=>{ const f=F(); if (f.safeOpen) return me('Già aperta. Non c\'è altro. Giuro.','Already open. Nothing else. I swear.'); if (!f.gaspareGone) return np('gaspare','Giù le mani dalla mia cassaforte, Ispettore! C\'è dentro il mio... pranzo.','Hands off my safe, Inspector! My... lunch is in there.');
  const c=await avCode(4, T('🔐 Cassaforte dell\'Assessore','🔐 The Councillor\'s safe')); if (c===null) return;
  if (c!=='1983') return me(c==='1987'?'Clic. Niente. Questo è l\'anno del nonno, non di Salvatore.':'Clic. Niente. Ci vuole l\'anno giusto, non quello della mia ultima doccia.', c==='1987'?'Click. Nothing. That\'s grandpa\'s year, not Salvatore\'s.':'Click. Nothing. Needs the right year, not my last shower.');
  await meAct('squat',1200); f.safeOpen=1; avSave(); drawRoom('municipio'); avSpawn('municipio');
  avAdd('vero'); avAdd('lettera');
  return me('CLAC! Dentro: il VERO Mestolo d\'Oro, pesante come un rimorso. E una lettera sigillata con la ceralacca nera e l\'impronta di un corvo.','CLACK! Inside: the REAL Golden Ladle, heavy as remorse. And a letter sealed with black wax stamped with a crow.'); });
avOn('look:portrait',()=>me('Il ritratto del sindaco. Il pittore è stato generoso coi capelli, col mento e con la dignità.','The mayor\'s portrait. The painter was generous with the hair, the chin and the dignity.'));
avOn('look:window',()=>me(F().gaspareGone?'La finestra da cui è saltato Gaspare. Sotto, i cassonetti dell\'umido. Uno si muove ancora.':'Una finestra aperta al primo piano. Comoda per le fughe. E per buttare giù i cittadini molesti.', F().gaspareGone?'The window Gaspare jumped from. Below, the compost bins. One is still moving.':'An open first-floor window. Handy for escapes. And for throwing out annoying citizens.'));
avOn('look:flag',()=>me('Una bandiera. Sventola anche senza vento, grazie al ventilatore dell\'assessore. Pagato col bilancio della cultura.','A flag. Flutters without wind, thanks to the councillor\'s fan. Paid for from the culture budget.'));
avOn('look:vero',()=>me('Il VERO Mestolo d\'Oro. Pesantissimo. Sotto il manico c\'è un\'incisione strana: linee, una X e un corvo barrato. Sembra un pezzo di mappa.','The REAL Golden Ladle. Very heavy. Under the handle there\'s a strange engraving: lines, an X and a crossed-out crow. Looks like a piece of a map.'));
avOn('use:vero:lente use:lente:vero',()=>me('Con la lente: l\'incisione è una mappa! Una costa, un vulcano, una X. E una scritta minuscola: "1 di 4". Il primo di quattro pezzi.','Through the glass: the engraving is a map! A coastline, a volcano, an X. And tiny writing: "1 of 4". The first of four pieces.'));
avOn('look:lettera use:me:lettera',()=>avLetter());
/* ================= FINALE ================= */
avOn('give:sindaco:vero',async()=>{ const f=F();
  if (f.nestDone && !f.ladleClean){ await npcAct('sindaco','scared',1200,'angry'); await np('sindaco','È COPERTO DI CACCA DI CORVO! Il sacro Mestolo di San Pancrazio! Non lo tocco neanche coi guanti del vescovo. Lavalo! Con l\'acqua benedetta, se possibile. O almeno con quella della fontana.','IT\'S COVERED IN CROW POOP! The sacred Ladle of Saint Pancras! I won\'t touch it even with the bishop\'s gloves. Wash it! With holy water, ideally. Or at least the fountain\'s.'); return; }
  avDel('vero'); f.end=1; avSave();
  await np('sindaco','Questo pesa! È VERO! IL MESTOLO D\'ORO DI SAN PANCRAZIO! Cittadini, la Sagra è salva!','This is heavy! It\'s REAL! THE GOLDEN LADLE OF SAINT PANCRAS! Citizens, the Festival is saved!');
  AV.npcs.forEach(n=>{ n.keep=1; npcPose(n,'cheer','happy'); }); setPose('cheer');
  await np('sindaco','E Gaspare! Il mio assessore! Voleva rifilarci quello di cioccolato e tenersi il vero! Lo farò arrestare... appena qualcuno lo tira fuori dai cassonetti.','And Gaspare! My own councillor! Wanted to fob us off with chocolate and keep the real one! I\'ll have him arrested... once someone pulls him out of the bins.');
  await np('sindaco','Ecco i tuoi mille Pippi! ...Meno la tassa sulla ricompensa, il bollo, i diritti di segreteria, il caffè di Nico e il mio disturbo: 200 Pippi. Netti. Nettissimi.','Here are your thousand Pippi! ...Minus reward tax, stamp duty, admin fees, Nico\'s coffee and my trouble: 200 Pippi. Net. Very net.');
  try { if (!f.paid){ f.paid=1; avSave(); LIFE.pippi+=200; saveLife(); } } catch(e){}
  await np('peppe','Duecento su mille. Il sindaco ha fatto il suo record: si è fregato l\'ottanta per cento. Di solito arriva al novanta.','Two hundred out of a thousand. The mayor set a record: only pocketed eighty percent. Usually it\'s ninety.');
  AV.npcs.forEach(n=>{ n.keep=0; npcPose(n,'dance','happy'); }); setPose('dance'); await avWait(2200);
  setPose('idle'); AV.npcs.forEach(n=>npcPose(n,'idle'));
  if (!f.readLetter) await me('Prima di festeggiare troppo... leggo quella lettera col corvo. Tocca la lettera nell\'inventario.','Before celebrating too much... let me read that crow letter. Tap the letter in the inventory.');
  else await avFinale(); });
async function avLetter(){ const f=F();
  await me('Rompo il sigillo. Calligrafia elegante, inchiostro nero, odore di risotto allo zafferano.','I break the seal. Elegant handwriting, black ink, smell of saffron risotto.');
  await avSay('voice', T('"Gaspare, verme. So che vuoi fregarmi. Il Mestolo non vale niente: è solo la chiave. Sotto il manico c\'è il primo dei quattro pezzi della Mappa dell\'Isola dei Pippi."','"Gaspare, you worm. I know you want to cheat me. The Ladle is worthless: it\'s only the key. Under the handle is the first of four pieces of the Map of Pippi Island."'));
  await avSay('voice', T('"Gli altri tre sono nascosti in paese da un vecchio pazzo chiamato Ernesto. Trovali, o la prossima piuma che vedi sarà sulla tua tomba. — Il Corvo"','"The other three were hidden in town by a mad old man named Ernesto. Find them, or the next feather you see will be on your grave. — The Crow"'));
  f.readLetter=1; avSave();
  await me('Ernesto. Il nonno. Il nonno ha nascosto una mappa del tesoro in paese, ha finto di andare in Svizzera e ha fatto il funerale con una bara di salami. E un pazzo vestito da corvo la vuole.','Ernesto. Grandpa. Grandpa hid a treasure map in town, faked going to Switzerland and held a funeral with a coffin of salami. And a lunatic dressed as a crow wants it.');
  await me('Il becco unto di risotto... chi mangia sempre il risotto alla Sagra senza pagare? ...No. Non può essere. Ci penso domani. Dopo il caffè.','Greasy with risotto... who always eats risotto at the Festival without paying? ...No. Can\'t be. I\'ll think about it tomorrow. After coffee.');
  if (f.end) await avFinale(); }
async function avFinale(){ const f=F(); if (f.endDone) return; f.endDone=1; avSave();
  avTrophy('end','Capitolo 1 completato.','Chapter 1 complete.'); if (!AV.st.hints) avTrophy('nohint','Capitolo 1 senza suggerimenti. Genio o bugiardo.','Chapter 1 with no hints. Genius or liar.');
  try { const u=unlockedPlaces(); ['porto','faro','municipio','cimitero'].forEach(x=>{ if (!u.includes(x)) u.push(x); }); localStorage.setItem('vainUnlock', JSON.stringify(u)); } catch(e){}
  await avSay('voice', T('Più tardi. Mentre il paese festeggia, sul campanile si staglia una sagoma nera col mantello. Una piuma cade lenta sulla piazza.','Later. As the town celebrates, a black cloaked silhouette stands on the bell tower. A feather drifts slowly down onto the piazza.'));
  await avSay('voice', T('La sagoma si pulisce il becco con un tovagliolo. Il tovagliolo ha una macchia gialla. Di zafferano.','The silhouette wipes its beak with a napkin. The napkin has a yellow stain. Saffron.'));
  const mins=Math.round((AV.st.play||0)/60000);
  sheet(`<div style="text-align:center"><div>${['vero','lettera','piuma'].map(k=>AV_ICONS[k]?`<svg viewBox="0 0 48 48" width="62" height="62">${AV_ICONS[k]}</svg>`:UI_IC(k,62)).join('')}</div><h3>${T('Fine del Capitolo 1: La Notte del Mestolo d\'Oro','End of Chapter 1: The Night of the Golden Ladle')}</h3><p>${T('La Sagra è salva, Gaspare è nei cassonetti, Tonino è in fuga e il Corvo ti osserva. 200 Pippi sono finiti nel tuo portafoglio anche nel gioco online.','The Festival is saved, Gaspare is in the bins, Tonino is on the run and the Crow is watching you. 200 Pippi went into your online wallet too.')}</p><p>⏱️ ${mins} min · 🪙 ${AV.st.coins.length}/${Object.keys(AV_COINS).length} · 🏆 ${AV.st.tro.length}/${AV_TROPHIES.length}</p><p><b>${T('Sbloccati nel gioco online: ⚓ Porto, 🗼 Faro, 🏛️ Municipio, ⚰️ Cimitero','Unlocked in the online game: ⚓ Harbour, 🗼 Lighthouse, 🏛️ Town Hall, ⚰️ Cemetery')}</b></p><p style="font-size:20px;letter-spacing:2px;color:#ffd166;margin:16px 0 4px">${T('CONTINUA…','TO BE CONTINUED…')}</p><p style="opacity:.75;margin-top:0">${T('Capitolo 2: La Società del Pippi','Chapter 2: The Pippi Society')}</p><button type="button" id="avEndOk" style="width:100%">OK</button></div>`);
  $('avEndOk').onclick=()=>closeSheet(); }
